create or replace function public.publish_house_rules(p_property_id uuid,p_title text,p_content jsonb,p_effective_from date default current_date) returns public.house_rules_versions language plpgsql security definer set search_path='' as $$ declare p public.properties; v public.house_rules_versions; n int; actor uuid; begin select * into p from public.properties where id=p_property_id for update; if not found then raise exception 'PROPERTY_NOT_FOUND'; end if; if public.can_manage_administration(p.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if p.rental_mode<>'BY_ROOMS' then raise exception 'HOUSE_RULES_REQUIRE_ROOM_RENTAL'; end if; if p_content is null or p_content='null'::jsonb then raise exception 'HOUSE_RULES_CONTENT_REQUIRED'; end if; select coalesce(max(version_number),0)+1 into n from public.house_rules_versions where property_id=p.id; update public.house_rules_versions set status='ARCHIVED' where property_id=p.id and status='ACTIVE'; select person_id into actor from public.accounts where auth_user_id=auth.uid(); insert into public.house_rules_versions(administration_id,property_id,version_number,title,content,status,effective_from,created_by_person_id) values(p.administration_id,p.id,n,coalesce(nullif(btrim(p_title),''),'Reglas de convivencia'),p_content,'ACTIVE',p_effective_from,actor) returning * into v; return v; end $$;